.ds-homepage { width: 100vw !important; max-width: 100vw !important; position: relative !important; left: 50% !important; right: 50% !important; margin-left: -50vw !important; margin-right: -50vw !important; box-sizing: border-box !important; overflow-x: hidden !important; font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif; color: #1e293b; background: #ffffff; line-height: 1.6; }
.entry-title, .entry-header, .post-title, .page-title, .wp-block-post-title, .site-header, #masthead, .site-branding, .header-footer-group, .theme-header, .custom-header, .nav-container { display: none !important; }
.ds-homepage * { box-sizing: border-box; margin: 0; padding: 0; }
:root { --ds-primary: #0066cc; --ds-primary-dark: #004c99; --ds-accent: #00a651; --ds-neutral: #f5f5f5; --ds-text: #1e293b; --ds-text-light: #64748b; }
.ds-container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }
.ds-section { padding: clamp(4rem, 10vw, 8rem) 0; position: relative; z-index: 1; }
.ds-bg-neutral { background-color: var(--ds-neutral); }
.ds-mt-4 { margin-top: 2rem; }

/* Typography */
h1, h2, h3, h4 { color: var(--ds-text); font-weight: 700; line-height: 1.2; }
.ds-gradient-text { background: linear-gradient(135deg, var(--ds-primary) 0%, var(--ds-primary-dark) 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; display: inline-block; margin-bottom: 1.5rem; font-size: clamp(2rem, 4vw, 3rem); }
.ds-section-header { text-align: center; margin-bottom: clamp(3rem, 6vw, 5rem); max-width: 800px; margin-left: auto; margin-right: auto; }

/* Header & Nav */
.ds-header { position: sticky; top: 0; z-index: 1000; background: rgba(255, 255, 255, 0.85); backdrop-filter: blur(12px) saturate(180%); -webkit-backdrop-filter: blur(12px) saturate(180%); border-bottom: 1px solid rgba(0, 0, 0, 0.06); box-shadow: 0 4px 30px rgba(0,0,0,0.03); transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); padding: 1rem 0; }
.ds-header-inner { display: flex; justify-content: space-between; align-items: center; }
.ds-logo { text-decoration: none; display: flex; align-items: center; }
.ds-logo-text { font-size: 1.5rem; font-weight: 800; color: var(--ds-primary); letter-spacing: -0.02em; }
.ds-nav { display: none; gap: 2rem; align-items: center; }
.ds-nav-link { text-decoration: none; position: relative; padding: 0.5rem 0; font-weight: 500; color: rgba(15, 23, 42, 0.8); transition: color 0.3s ease; }
.ds-nav-link::after { content: ""; position: absolute; bottom: 0; left: 0; width: 100%; height: 2px; background: var(--ds-primary); transform: scaleX(0); transform-origin: right; transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
.ds-nav-link:hover { color: var(--ds-primary); }
.ds-nav-link:hover::after { transform: scaleX(1); transform-origin: left; }

/* Mobile Menu Hack */
.ds-mobile-menu-toggle { display: none; }
.ds-mobile-menu-label { display: flex; flex-direction: column; gap: 6px; cursor: pointer; z-index: 1001; }
.ds-mobile-menu-label span { display: block; width: 28px; height: 3px; background: var(--ds-text); border-radius: 3px; transition: all 0.3s ease; }
.ds-mobile-menu-toggle:checked ~ .ds-nav { display: flex; flex-direction: column; position: absolute; top: 100%; left: 0; width: 100%; background: #ffffff; padding: 2rem 1.5rem; box-shadow: 0 10px 25px rgba(0,0,0,0.1); border-top: 1px solid rgba(0,0,0,0.05); gap: 1.5rem; align-items: flex-start; }
@media (min-width: 768px) { .ds-mobile-menu-label { display: none; } .ds-nav { display: flex !important; flex-direction: row; position: static; padding: 0; box-shadow: none; background: transparent; border: none; align-items: center; } }

/* Buttons & Badges */
.ds-btn { display: inline-flex; align-items: center; justify-content: center; padding: 0.875rem 2rem; border-radius: 50px; font-weight: 600; text-decoration: none; transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1); cursor: pointer; border: none; }
.ds-btn-primary { background: linear-gradient(135deg, var(--ds-primary) 0%, var(--ds-primary-dark) 100%); color: #ffffff; box-shadow: 0 4px 15px rgba(0, 102, 204, 0.3); }
.ds-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 25px rgba(0, 102, 204, 0.4); color: #ffffff; }
.ds-btn-secondary { background: #ffffff; color: var(--ds-text); border: 1px solid rgba(0,0,0,0.1); }
.ds-btn-secondary:hover { border-color: var(--ds-primary); color: var(--ds-primary); transform: translateY(-2px); }
.ds-badge { display: inline-flex; align-items: center; padding: 0.5rem 1.25rem; background: rgba(0, 102, 204, 0.08); color: var(--ds-primary); border-radius: 9999px; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; border: 1px solid rgba(0, 102, 204, 0.15); margin-bottom: 1.25rem; }
.ds-badge-light { background: rgba(255,255,255,0.15); color: #ffffff; border-color: rgba(255,255,255,0.3); backdrop-filter: blur(4px); }

/* Cards */
.ds-card { background: #ffffff; border-radius: 20px; border: 1px solid rgba(0,0,0,0.05); box-shadow: 0 10px 30px rgba(0,0,0,0.02); transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1); overflow: hidden; }
.ds-card:hover { transform: translateY(-8px); box-shadow: 0 20px 40px rgba(0,0,0,0.08); border-color: rgba(0, 102, 204, 0.2); }

/* Hero Section */
.ds-hero { position: relative; min-height: clamp(600px, 80vh, 900px); display: flex; align-items: center; padding: clamp(6rem, 15vw, 10rem) 0; overflow: hidden; color: #ffffff; }
.ds-hero-bg { position: absolute; inset: 0; z-index: 0; }
.ds-hero-bg img { width: 100%; height: 100%; object-fit: cover; }
.ds-hero-overlay { position: absolute; inset: 0; background: linear-gradient(135deg, rgba(0, 102, 204, 0.92) 0%, rgba(0, 166, 81, 0.7) 100%); mix-blend-mode: multiply; }
.ds-hero-content { position: relative; z-index: 1; max-width: 700px; }
.ds-hero h1 { font-size: clamp(2.5rem, 6vw, 4.5rem); font-weight: 800; line-height: 1.1; margin-bottom: 1.5rem; color: #ffffff; }
.ds-hero p { font-size: clamp(1.125rem, 2.5vw, 1.5rem); margin-bottom: 2.5rem; opacity: 0.95; max-width: 600px; line-height: 1.6; }
.ds-hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }
.ds-hero-shape { position: absolute; bottom: -1px; left: 0; width: 100%; height: clamp(50px, 10vw, 120px); background: #ffffff; clip-path: polygon(0 100%, 100% 100%, 100% 0, 0 100%); z-index: 1; }

/* Intro Section */
.ds-intro-grid { display: grid; grid-template-columns: 1fr; gap: 3rem; align-items: center; }
@media (min-width: 992px) { .ds-intro-grid { grid-template-columns: 1fr 1fr; gap: 5rem; } }
.ds-intro-text p { font-size: 1.125rem; color: var(--ds-text-light); }
.ds-intro-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; }
.ds-stat-card { padding: 2rem; text-align: center; }
.ds-stat-value { font-size: 2.5rem; font-weight: 800; color: var(--ds-primary); margin-bottom: 0.5rem; }
.ds-stat-label { font-size: 0.875rem; font-weight: 600; color: var(--ds-text-light); text-transform: uppercase; letter-spacing: 0.05em; }

/* Services Section */
.ds-services-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 2rem; }
.ds-service-card { display: flex; flex-direction: column; }
.ds-service-img { height: 200px; overflow: hidden; }
.ds-service-img img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1); }
.ds-service-card:hover .ds-service-img img { transform: scale(1.06); }
.ds-service-content { padding: 2rem; flex-grow: 1; }
.ds-service-content h3 { margin-bottom: 1rem; font-size: 1.25rem; }
.ds-service-content p { color: var(--ds-text-light); font-size: 0.95rem; }

/* Reviews Section */
.ds-reviews-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 2rem; }
.ds-review-card { padding: 2.5rem; display: flex; flex-direction: column; justify-content: space-between; }
.ds-stars { color: #fbbf24; font-size: 1.25rem; margin-bottom: 1.5rem; letter-spacing: 2px; }
.ds-review-text { font-size: 1.125rem; font-style: italic; margin-bottom: 2rem; color: var(--ds-text); line-height: 1.7; }
.ds-review-author { display: flex; justify-content: space-between; align-items: center; border-top: 1px solid rgba(0,0,0,0.05); padding-top: 1.5rem; }
.ds-review-author strong { color: var(--ds-primary); }
.ds-review-author span { font-size: 0.875rem; color: var(--ds-text-light); }

/* Gallery Section */
.ds-gallery-grid { display: grid; grid-template-columns: 1fr; gap: 2rem; }
.ds-gallery-item { height: clamp(300px, 50vw, 500px); overflow: hidden; }
.ds-gallery-item img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1); }
.ds-gallery-item:hover img { transform: scale(1.04); }

/* Contact Section */
.ds-contact-grid { display: grid; grid-template-columns: 1fr; gap: 4rem; }
@media (min-width: 992px) { .ds-contact-grid { grid-template-columns: 1fr 1fr; align-items: center; } }
.ds-contact-info p { color: var(--ds-text-light); margin-bottom: 2rem; font-size: 1.125rem; }
.ds-contact-details { display: flex; flex-direction: column; gap: 1.5rem; }
.ds-contact-item { display: flex; flex-direction: column; gap: 0.25rem; }
.ds-contact-item strong { color: var(--ds-primary); font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.05em; }
.ds-contact-item a, .ds-contact-item span { color: var(--ds-text); text-decoration: none; font-size: 1.125rem; font-weight: 500; }
.ds-contact-item a:hover { color: var(--ds-primary); }
.ds-contact-map { height: 400px; position: relative; overflow: hidden; display: flex; align-items: center; justify-content: center; background: #e2e8f0; }
.ds-map-placeholder { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; }
.ds-map-placeholder .ds-btn { position: absolute; z-index: 2; }

/* Footer */
.ds-footer { background: #0f172a; color: #ffffff; padding: 4rem 0 2rem; }
.ds-footer-content { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 2rem; margin-bottom: 3rem; }
.ds-footer-brand h3 { color: #ffffff; margin-bottom: 0.5rem; }
.ds-footer-brand p { color: #94a3b8; }
.ds-footer-links { display: flex; gap: 2rem; }
.ds-footer-links a { color: #e2e8f0; text-decoration: none; transition: color 0.3s; }
.ds-footer-links a:hover { color: var(--ds-primary); }
.ds-footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 2rem; text-align: center; color: #64748b; font-size: 0.875rem; }

/* Animations & Effects */
.ds-reveal { opacity: 0; transform: translateY(30px); animation: dsFadeInUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
.ds-delay-1 { animation-delay: 0.15s; }
.ds-delay-2 { animation-delay: 0.3s; }
.ds-delay-3 { animation-delay: 0.45s; }
.ds-delay-4 { animation-delay: 0.6s; }
@keyframes dsFadeInUp { to { opacity: 1; transform: translateY(0); } }

.ds-glow-1, .ds-glow-2 { position: absolute; width: clamp(200px, 40vw, 400px); height: clamp(200px, 40vw, 400px); border-radius: 50%; filter: blur(100px); opacity: 0.06; pointer-events: none; z-index: 0; }
.ds-glow-1 { background: var(--ds-primary); top: 15%; left: -10%; animation: dsFloat 18s infinite alternate ease-in-out; }
.ds-glow-2 { background: var(--ds-accent); bottom: 25%; right: -10%; animation: dsFloat 24s infinite alternate-reverse ease-in-out; }
@keyframes dsFloat { 0% { transform: translate(0, 0) scale(1); } 50% { transform: translate(6%, 6%) scale(1.08); } 100% { transform: translate(0, 0) scale(1); } }

@media (prefers-reduced-motion: reduce) { .ds-homepage * { transition: none !important; transform: none !important; animation: none !important; } }
